macro_rules! deps {
    () => {
        Matches!();
        Regex!();
        Match!();
    };
}

macro_rules! RegexSet {
    () => {
        deps!();
        # [doc = " Match multiple, possibly overlapping, regexes in a single search."] # [doc = ""] # [doc = " A regex set corresponds to the union of zero or more regular expressions."] # [doc = " That is, a regex set will match a haystack when at least one of its"] # [doc = " constituent regexes matches. A regex set as its formulated here provides a"] # [doc = " touch more power: it will also report *which* regular expressions in the"] # [doc = " set match. Indeed, this is the key difference between regex sets and a"] # [doc = " single `Regex` with many alternates, since only one alternate can match at"] # [doc = " a time."] # [doc = ""] # [doc = " For example, consider regular expressions to match email addresses and"] # [doc = " domains: `[a-z]+@[a-z]+\\.(com|org|net)` and `[a-z]+\\.(com|org|net)`. If a"] # [doc = " regex set is constructed from those regexes, then searching the haystack"] # [doc = " `foo@example.com` will report both regexes as matching. Of course, one"] # [doc = " could accomplish this by compiling each regex on its own and doing two"] # [doc = " searches over the haystack. The key advantage of using a regex set is"] # [doc = " that it will report the matching regexes using a *single pass through the"] # [doc = " haystack*. If one has hundreds or thousands of regexes to match repeatedly"] # [doc = " (like a URL router for a complex web application or a user agent matcher),"] # [doc = " then a regex set *can* realize huge performance gains."] # [doc = ""] # [doc = " # Limitations"] # [doc = ""] # [doc = " Regex sets are limited to answering the following two questions:"] # [doc = ""] # [doc = " 1. Does any regex in the set match?"] # [doc = " 2. If so, which regexes in the set match?"] # [doc = ""] # [doc = " As with the main [`Regex`][crate::Regex] type, it is cheaper to ask (1)"] # [doc = " instead of (2) since the matching engines can stop after the first match"] # [doc = " is found."] # [doc = ""] # [doc = " You cannot directly extract [`Match`][crate::Match] or"] # [doc = " [`Captures`][crate::Captures] objects from a regex set. If you need these"] # [doc = " operations, the recommended approach is to compile each pattern in the set"] # [doc = " independently and scan the exact same haystack a second time with those"] # [doc = " independently compiled patterns:"] # [doc = ""] # [doc = " ```"] # [doc = " use regex::{Regex, RegexSet};"] # [doc = ""] # [doc = " let patterns = [\"foo\", \"bar\"];"] # [doc = " // Both patterns will match different ranges of this string."] # [doc = " let hay = \"barfoo\";"] # [doc = ""] # [doc = " // Compile a set matching any of our patterns."] # [doc = " let set = RegexSet::new(patterns).unwrap();"] # [doc = " // Compile each pattern independently."] # [doc = " let regexes: Vec<_> = set"] # [doc = "     .patterns()"] # [doc = "     .iter()"] # [doc = "     .map(|pat| Regex::new(pat).unwrap())"] # [doc = "     .collect();"] # [doc = ""] # [doc = " // Match against the whole set first and identify the individual"] # [doc = " // matching patterns."] # [doc = " let matches: Vec<&str> = set"] # [doc = "     .matches(hay)"] # [doc = "     .into_iter()"] # [doc = "     // Dereference the match index to get the corresponding"] # [doc = "     // compiled pattern."] # [doc = "     .map(|index| &regexes[index])"] # [doc = "     // To get match locations or any other info, we then have to search the"] # [doc = "     // exact same haystack again, using our separately-compiled pattern."] # [doc = "     .map(|re| re.find(hay).unwrap().as_str())"] # [doc = "     .collect();"] # [doc = ""] # [doc = " // Matches arrive in the order the constituent patterns were declared,"] # [doc = " // not the order they appear in the haystack."] # [doc = " assert_eq!(vec![\"foo\", \"bar\"], matches);"] # [doc = " ```"] # [doc = ""] # [doc = " # Performance"] # [doc = ""] # [doc = " A `RegexSet` has the same performance characteristics as `Regex`. Namely,"] # [doc = " search takes `O(m * n)` time, where `m` is proportional to the size of the"] # [doc = " regex set and `n` is proportional to the length of the haystack."] # [doc = ""] # [doc = " # Trait implementations"] # [doc = ""] # [doc = " The `Default` trait is implemented for `RegexSet`. The default value"] # [doc = " is an empty set. An empty set can also be explicitly constructed via"] # [doc = " [`RegexSet::empty`]."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This shows how the above two regexes (for matching email addresses and"] # [doc = " domains) might work:"] # [doc = ""] # [doc = " ```"] # [doc = " use regex::RegexSet;"] # [doc = ""] # [doc = " let set = RegexSet::new(&["] # [doc = "     r\"[a-z]+@[a-z]+\\.(com|org|net)\","] # [doc = "     r\"[a-z]+\\.(com|org|net)\","] # [doc = " ]).unwrap();"] # [doc = ""] # [doc = " // Ask whether any regexes in the set match."] # [doc = " assert!(set.is_match(\"foo@example.com\"));"] # [doc = ""] # [doc = " // Identify which regexes in the set match."] # [doc = " let matches: Vec<_> = set.matches(\"foo@example.com\").into_iter().collect();"] # [doc = " assert_eq!(vec![0, 1], matches);"] # [doc = ""] # [doc = " // Try again, but with a haystack that only matches one of the regexes."] # [doc = " let matches: Vec<_> = set.matches(\"example.com\").into_iter().collect();"] # [doc = " assert_eq!(vec![1], matches);"] # [doc = ""] # [doc = " // Try again, but with a haystack that doesn't match any regex in the set."] # [doc = " let matches: Vec<_> = set.matches(\"example\").into_iter().collect();"] # [doc = " assert!(matches.is_empty());"] # [doc = " ```"] # [doc = ""] # [doc = " Note that it would be possible to adapt the above example to using `Regex`"] # [doc = " with an expression like:"] # [doc = ""] # [doc = " ```text"] # [doc = " (?P<email>[a-z]+@(?P<email_domain>[a-z]+[.](com|org|net)))|(?P<domain>[a-z]+[.](com|org|net))"] # [doc = " ```"] # [doc = ""] # [doc = " After a match, one could then inspect the capture groups to figure out"] # [doc = " which alternates matched. The problem is that it is hard to make this"] # [doc = " approach scale when there are many regexes since the overlap between each"] # [doc = " alternate isn't always obvious to reason about."] # [derive (Clone)] pub struct RegexSet { pub (crate) meta : meta :: Regex , pub (crate) patterns : alloc :: sync :: Arc < [String] > , }
    };
}

RegexSet!();